package org.jetbrains.hexana.ui.panel

import com.intellij.openapi.fileEditor.FileEditorManager
import com.intellij.openapi.project.Project
import com.intellij.testFramework.LightVirtualFile
import org.jetbrains.hexana.mcp.scripting.BinaryProviderApiSummary
import org.jetbrains.hexana.shared.scripting.ScriptApiReference

/**
 * Opens the two bundled scripting references in read-only editor tabs, as linked
 * from [AddScriptTabDialog].
 *
 * The references themselves are generated by `:mcp:scripting:generateHexanaScriptingDts`
 * and bundled as plugin resources; this only shows them, falling back to
 * generating on the fly if the resource is somehow missing.
 */
internal object ScriptingApiReferenceEditor {

    /** Opens the curated scripting reference — the one a user should read first. */
    fun showDts(project: Project) {
        val name = BinaryProviderApiSummary.CURATED_DTS_NAME
        openReadOnly(project, name, bundled(name) ?: ScriptApiReference.dts())
    }

    /** Opens the reflective `binary.raw` type dump. */
    fun showRawDts(project: Project) {
        val name = BinaryProviderApiSummary.RAW_DTS_NAME
        openReadOnly(project, name, bundled(name) ?: BinaryProviderApiSummary.generateRawDts())
    }

    /**
     * Reads a reference out of this plugin's resources, so a reader sees the same
     * file the script editor resolves against rather than a freshly reflected one.
     */
    private fun bundled(name: String): String? =
        ScriptingApiReferenceEditor::class.java.getResourceAsStream("/$name")
            ?.bufferedReader()?.readText()

    private fun openReadOnly(project: Project, name: String, content: String) {
        val vf = LightVirtualFile(name, content).apply { isWritable = false }
        FileEditorManager.getInstance(project).openFile(vf, true)
    }
}
